return function(ctx,target,text) local tip=Instance.new("TextLabel",ctx.TooltipLayer);tip.Size=UDim2.fromOffset(160,28);tip.BackgroundColor3=ctx.Theme:Get("Overlay");tip.TextColor3=Color3.new(1,1,1);tip.Text=tostring(text);tip.Font=Enum.Font.Gotham;tip.TextSize=12;tip.Visible=false;tip.ZIndex=1000;Instance.new("UICorner",tip).CornerRadius=UDim.new(0,7);ctx.Maid:Give(target.MouseEnter:Connect(function()local p=target.AbsolutePosition;tip.Position=UDim2.fromOffset(p.X,p.Y-32);tip.Visible=true end));ctx.Maid:Give(target.MouseLeave:Connect(function()tip.Visible=false end));return Component.new(tip,ctx) end
